"""Independent reference implementations written straight from the spec.
Deliberately slow/naive; used only for differential testing."""
from math import gcd
from fractions import Fraction
import copy

PS = 10**6
NS = 10**9
INF = float('inf')

# ---------------- calibration ----------------

def ref_calibration(profile):
    """Return ('ok', D, H, C) or ('bad',) via Bellman-Ford per source."""
    K = profile['groups']
    edges = []
    for i, (a, b, L, U) in enumerate(profile['measurements']):
        edges.append((a, b, U, 2 * i))
        edges.append((b, a, -L, 2 * i + 1))
    # feasibility: BF from super source
    dist = [0] * K
    for it in range(K + 1):
        upd = False
        for a, b, w, i in edges:
            if dist[a] + w < dist[b]:
                dist[b] = dist[a] + w
                upd = True
        if not upd:
            break
    else:
        if upd:
            return ('bad',)
    D = [[0] * K for _ in range(K)]
    for s in range(K):
        d = [INF] * K
        d[s] = 0
        for _ in range(K - 1):
            for a, b, w, i in edges:
                if d[a] != INF and d[a] + w < d[b]:
                    d[b] = d[a] + w
        D[s] = d
    jit = profile['jitter_ps']
    H = [[0] * K for _ in range(K)]
    C = [[0] * K for _ in range(K)]
    for a in range(K):
        for b in range(K):
            hi = D[a][b]; lo = -D[b][a]
            H[a][b] = (hi - lo) * PS // 2 + (jit[a] + jit[b]) * PS
            C[a][b] = (hi + lo) * PS // 2
    return ('ok', D, H, C)

# ---------------- fabric calendar ----------------

def ref_fabric_setup(fabric):
    N = fabric['n']; T = fabric['interval_ns']; S = fabric['slice_ns']
    O = fabric['offset_ns']
    Q = len(fabric['slices'])
    mod = Q * S
    P = mod // gcd(T, mod)
    phase_slice = [((O + p * T) // S) % Q for p in range(P)]
    phase_rho = [(O + p * T) % S for p in range(P)]
    # effective rates (ppb) per device per phase
    V = [[fabric['drift_ppb'][i]] * P for i in range(N)]
    for (nd, st, en, ex) in fabric['heat']:
        for p in range(st, en):
            V[nd][p] += ex
    return P, N, T, S, phase_slice, phase_rho, V

def ref_dir_info(fabric, code):
    l = code // 2
    dr = code % 2
    lk = fabric['links'][l]
    e0 = lk['ends'][0]; e1 = lk['ends'][1]
    frm = e0 if dr == 0 else e1
    to = e1 if dr == 0 else e0
    d = lk['delay_ns'][dr]
    q = lk['defer_rounds'][dr]
    T = fabric['interval_ns']
    m = -(-d // T)
    return frm, to, d, q, m, m + q

def ref_blocked(fabric, l, p):
    """flight window blackout check at phase p for given dir info"""
    T = fabric['interval_ns']
    return None

def ref_hop_eligible(fabric, code, p, g, P):
    l = code // 2
    frm, to, d, q, m, L = ref_dir_info(fabric, code)
    S = fabric['slice_ns']
    if l not in fabric['slices'][ref_phase_slice_cached(p)]:
        return False
    # blackout: intervals [p, p+m-1]
    for (bl, st, en) in fabric['blackouts']:
        if bl != l:
            continue
        for x in range(p, p + m):
            if st <= (x % P) < en:
                return False
    rho = ref_phase_rho_cached(p)
    if rho < g or rho + d + g > S:
        return False
    return True

_C = {}
def ref_phase_slice_cached(p):
    return _C['fs'][p % _C['P']]
def ref_phase_rho_cached(p):
    return _C['fr'][p % _C['P']]

def ref_aging(VR, wnode, p, d, m, q, P, T):
    """receiver aging in as over [tr, pa) starting at phase p"""
    vh = VR[wnode]  # as per interval list
    part = m * T - d
    tot = part * vh[(p + d // T) % P]
    for j in range(p + m, p + m + q):
        tot += vh[j % P]
    return tot

def ref_plan(profile, fabric):
    cal = ref_calibration(profile)
    if cal[0] == 'bad':
        return {'status': 'inconsistent'}
    _, D, H, C = cal
    P, N, T, S, fsl, fro, Vppb = ref_fabric_setup(fabric)
    _C['P'] = P; _C['fs'] = fsl; _C['fr'] = fro
    VR = [[Vppb[i][p] * T for p in range(P)] for i in range(N)]
    anchors = fabric['anchors']
    guards = fabric['guards_ns']
    rc = fabric['reconfig_ns']

    def anchored(i, p):
        return any(a == i and a_st <= p < a_en for (a, a_st, a_en) in anchors)

    # per phase, list of (code, L, cost_err) eligible ignoring guard-size
    hops_at = {}
    for p in range(P):
        lst = []
        for l, lid in enumerate(fabric['slices'][fsl[p]]):
            for dr in (0, 1):
                code = 2 * lid + dr
                frm, to, d, q, m, L = ref_dir_info(fabric, code)
                # blackout
                bl = False
                for (b2, st, en) in fabric['blackouts']:
                    if b2 != lid:
                        continue
                    for x in range(p, p + m):
                        if st <= (x % P) < en:
                            bl = True
                            break
                    if bl:
                        break
                if bl:
                    continue
                gmax = min(fro[p], S - d - fro[p])
                gu = frm[2]; gw = to[2]
                cost = H[gu][gw] + ref_aging(VR, to[0], p, d, m, q, P, T)
                lst.append((code, frm[0], to[0], L, cost, gmax))
        hops_at[p] = lst

    def envelope_for(g):
        """time-expanded DP over absolute boundaries; returns B,A per cell."""
        # sufficient horizon: lineages simple -> <= 16*V steps
        VV = P * N
        Tmax = 16 * VV + 2 * P + 2
        NEG = None
        # E[i] = (err, age) lexicographic best lineage ending at boundary t
        Em = [dict() for _ in range(Tmax + 1)]
        prevE = None
        # store per boundary arrays
        Earr = [[None] * N for _ in range(Tmax + 1)]
        for t in range(Tmax + 1):
            p = t % P
            for i in range(N):
                if anchored(i, p):
                    Earr[t][i] = (0, 0)
            if t > 0:
                for i in range(N):
                    if Earr[t - 1][i] is not None:
                        e, a = Earr[t - 1][i]
                        cand = (e + VR[i][(t - 1) % P], a + 1)
                        cur = Earr[t][i]
                        if cur is None or cand < cur:
                            Earr[t][i] = cand
                for (code, fn, wn, L, cost, gmax) in hops_at[p]:
                    if gmax < g:
                        continue
                    if t >= L and Earr[t - L][fn] is not None:
                        e, a = Earr[t - L][fn]
                        cand = (e + cost, a + L)
                        cur = Earr[t][wn]
                        if cur is None or cand < cur:
                            Earr[t][wn] = cand
        B = [[None] * N for _ in range(P)]
        A = [[None] * N for _ in range(P)]
        start = Tmax // 2  # min over all t is fine too, but later windows safer
        for p in range(P):
            for i in range(N):
                best = None
                for t in range(p, Tmax + 1, P):
                    v = Earr[t][i]
                    if v is not None and (best is None or v < best):
                        best = v
                if best is not None:
                    B[p][i] = best[0]
                    A[p][i] = best[1]
        return B, A, Earr

    peaks = []
    sel = None
    BA = {}
    for g in guards:
        B, A, Earr = envelope_for(g)
        BA[g] = (B, A, Earr)
        pk = 0
        okall = True
        for p in range(P):
            for i in range(N):
                if B[p][i] is None:
                    okall = False
                    break
                val = B[p][i] + VR[i][p]
                if val > pk:
                    pk = val
            if not okall:
                break
        peaks.append(pk if okall else None)
        if sel is None and okall and pk + rc * NS <= g * NS:
            sel = g
    out = {'P': P, 'peaks': peaks, 'guard': sel}
    if sel is None:
        return out
    B, A, Earr = BA[sel]
    # warmup from E: smallest k with all boundaries kP..kP+P-1 at (i,p) B
    warm = None
    for k in range(0, Tmax // P + 1):
        good = True
        for p in range(P):
            t = k * P + p
            if t > Tmax:
                good = False
                break
            for i in range(N):
                if B[p][i] is None or Earr[t][i] is None or Earr[t][i][0] != B[p][i]:
                    good = False
                    break
            if not good:
                break
        if good:
            warm = k
            break
    out['bounds'] = B
    out['ages'] = A
    out['warmup'] = warm
    return out

# ---------------- replay reference ----------------

def ref_replay(profile, fabric, guard, trace):
    cal = ref_calibration(profile)
    if cal[0] == 'bad':
        return {'status': 'inconsistent'}
    _, D, H, C = cal
    P, N, T, S, fsl, fro, Vppb = ref_fabric_setup(fabric)
    _C['P'] = P; _C['fs'] = fsl; _C['fr'] = fro
    VR = [[Vppb[i][p] * T for p in range(P)] for i in range(N)]
    R = trace['rounds']
    rates = trace['rates_ppb']
    bias = trace['bias_ps']
    lost = set(trace['lost'])
    anchors = fabric['anchors']
    g = guard

    err = [None] * N
    bnd = [None] * N
    gen = [0] * N
    pend = []  # (apply_tick, id, src, dst, e, b, gs, gd)
    status = {}
    delivered = adopted = unknowns = stale = 0
    peak = 0
    always_known = True
    states = {}

    for t in range(R + 1):
        p = t % P
        if t > 0:
            for i in range(N):
                if bnd[i] is not None:
                    err[i] = err[i] + rates[t - 1][i] * T
                    bnd[i] = bnd[i] + VR[i][(t - 1) % P]
                    if err[i] is not None:
                        peak = max(peak, abs(err[i]))
        for (rt, rn) in trace['reboots']:
            if rt == t:
                gen[rn] += 1
                err[rn] = None
                bnd[rn] = None
        for (an, ast, aen) in anchors:
            if ast <= ((t - 0) % P) < aen and t >= 0:
                # anchor service at boundary t (available from boundary 0)
                if t % P >= ast and t % P < aen and (t // P) * P + (t % P) == t:
                    pass
                err[an] = 0
                bnd[an] = 0
        # due applications
        due = [x for x in pend if x[0] == t]
        for i in range(N):
            pk = [x for x in due if x[3] == i]
            if not pk:
                continue
            delivered += len(pk)
            remain = []
            for x in pk:
                if x[6] != gen[x[2]] or x[7] != gen[i]:
                    stale += 1
                    continue
                if x[4] is None:
                    unknowns += 1
                    continue
                remain.append(x)
            if remain:
                best = min(remain, key=lambda x: (x[5], x[1]))
                held = bnd[i]
                if held is None or best[5] < held:
                    err[i] = best[4]
                    bnd[i] = best[5]
                    adopted += 1
                    states.setdefault(('ad', t), {})[i] = best[1]
                    peak = max(peak, abs(best[4]))
        pend = [x for x in pend if x[0] != t]
        if any(b is None for b in bnd):
            always_known = False
        if t in trace['queries']:
            st = {"bounds_as": bnd[:], "errors_as": err[:],
                  "adopted": [states.get(('ad', t), {}).get(i) for i in range(N)],
                  "generations": gen[:]}
            states[t] = st
        # sends
        sd = sorted([x for x in trace['sends'] if x[1] == t], key=lambda x: x[0])
        used = set()
        for (sid, tick, code, jit) in sd:
            l = code // 2
            frmo, too, d, q, m, L = ref_dir_info(fabric, code)
            if l not in fabric['slices'][fsl[p]]:
                status[sid] = 'not_in_slice'
                continue
            bl = False
            for (bl2, bst, ben) in fabric['blackouts']:
                if bl2 != l:
                    continue
                for x in range(t, t + m):
                    if bst <= (x % P) < ben:
                        bl = True
                if bl:
                    break
            if bl:
                status[sid] = 'blackout'
                continue
            if fro[p] < g or fro[p] + d + g > S:
                status[sid] = 'guard'
                continue
            key = (frmo[0], frmo[1])
            if key in used:
                status[sid] = 'port_busy'
                continue
            used.add(key)
            if sid in lost:
                status[sid] = 'lost'
                continue
            status[sid] = 'sent'
            pa = t + L
            if err[frmo[0]] is None:
                ce = None
                cb = None
            else:
                ce = err[frmo[0]] + (bias[too[2]] - bias[frmo[2]]) * PS + jit - C[frmo[2]][too[2]]
                cb = bnd[frmo[0]] + H[frmo[2]][too[2]]
                cb += (m * T - d) * VR[too[0]][(t + d // T) % P]
                for j in range(t + m, pa):
                    cb += VR[too[0]][j % P]
                if ce is not None:
                    if m * T - d:
                        ce += rates[t + d // T][too[0]] * (m * T - d)
                    for j in range(t + m, pa):
                        ce += rates[j][too[0]] * T
            if pa > R:
                continue
            pend.append((pa, sid, frmo[0], too[0], ce, cb, gen[frmo[0]], gen[too[0]]))
    pending_cnt = len(pend)
    out = {"status": "ok",
           "states": [states[q] for q in trace['queries']],
           "send_status": [status[x[0]] for x in trace['sends']],
           "delivered": delivered, "adopted": adopted,
           "unknown_payloads": unknowns, "stale_payloads": stale,
           "pending": pending_cnt, "peak_known_abs_as": peak,
           "always_known": always_known}
    return out
